// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.agent.accessibilityimport timber.log.Timberimport com.roshan.persona.system.handler.NousAccessibilityServiceInterface/** * NOUS — Accessibility Service Interface Implementation (Module 9 v1 — Step 9.1). * * REAL implementation of Module 10's [NousAccessibilityServiceInterface]. * This REPLACES [com.roshan.persona.system.handler.NoopAccessibilityService] * which was the stub used until Module 9 shipped. * * ## How it works * * This class delegates to [AccessibilityServiceRegistry.getInstance()] — * the static holder for the active [NousAccessibilityService] instance. * * When the service is connected (user enabled it in Settings): *  - `isServiceEnabled()` → true *  - `performGlobalAction(action)` → delegates to real AccessibilityService * * When the service is NOT connected (user hasn't enabled it): *  - `isServiceEnabled()` → false *  - `performGlobalAction(action)` → false (graceful failure) * * ## Hilt Wiring * * Module 9's `AgentModule` (Step 9.8) will bind this class as * [NousAccessibilityServiceInterface], OVERRIDING Module 10's * `NoopAccessibilityService` binding. * * @see <a href="docs/strategy/module-9-agent-strategy-v1.md">§Architecture → Real Service Wiring</a> */class NousAccessibilityServiceInterfaceImpl : NousAccessibilityServiceInterface {    companion object {        private const val TAG = "A11yInterfaceImpl"    }    /**     * True if the NOUS AccessibilityService is connected.     *     * Checks [AccessibilityServiceRegistry.isActive] — the static registry     * that holds the active service instance.     */    override fun isServiceEnabled(): Boolean {        val active = AccessibilityServiceRegistry.isActive()        Timber.tag(TAG).d("isServiceEnabled: $active.")        return active    }    /**     * Perform a global accessibility action (REAL Android API delegation).     *     * Delegates to [NousAccessibilityService.executeGlobalAction] which calls     * the real `AccessibilityService.performGlobalAction()`.     *     * Supported actions (from [com.roshan.persona.system.handler.AccessibilityActions]):     *  - GLOBAL_ACTION_BACK (1)     *  - GLOBAL_ACTION_HOME (2)     *  - GLOBAL_ACTION_RECENTS (3)     *  - GLOBAL_ACTION_NOTIFICATIONS (4)     *  - GLOBAL_ACTION_QUICK_SETTINGS (5)     *  - GLOBAL_ACTION_DISMISS_NOTIFICATION_SHADE (14)     *  - GLOBAL_ACTION_LOCK_SCREEN (8)     *  - GLOBAL_ACTION_TAKE_SCREENSHOT (15)     *     * @param action one of `AccessibilityService.GLOBAL_ACTION_*` constants.     * @return true if the action was performed successfully.     */    override fun performGlobalAction(action: Int): Boolean {        val service = AccessibilityServiceRegistry.getInstance()        if (service == null) {            Timber.tag(TAG).w("AccessibilityService not connected — cannot perform action $action.")            return false        }        val result = service.executeGlobalAction(action)        Timber.tag(TAG).d("performGlobalAction($action) → $result.")        return result    }}